const test = require('node:test');
const assert = require('node:assert/strict');
const { setFilter } = require('../src/saved-filter.cjs');

test("existing name has one value after set", () => {
  assert.deepEqual(setFilter('tag=oak&view=grid&tag=elm&tag=ash', 'tag', 'cedar'), [['tag', 'cedar'], ['view', 'grid']]);
  assert.deepEqual(setFilter('tag=oak&view=grid', 'tag', ''), [['tag', ''], ['view', 'grid']]);
});

test("missing name is created and unrelated entries survive", () => {
  assert.deepEqual(setFilter('view=grid&view=list', 'tag', 'cedar'), [['view', 'grid'], ['view', 'list'], ['tag', 'cedar']]);
  assert.deepEqual(setFilter('', 'tag', 'cedar'), [['tag', 'cedar']]);
});

